from collections import Counter
from datetime import datetime
from os import path
from typing import Dict, Iterator, List, Tuple, Any, Union

from robot.api.deco import keyword
from six import with_metaclass
from ta_egate_cmd_parser import ta_egate_cmd_parser

from ta_tti_collector.tti_collector import TtiCollector
from ta_tti_parser.parser import TtiDatParser
from ta_tti_parser.merger import TxtFileMerger
from ta_tti_parser.trace import Filters, Trace
from ta_tti_parser.utils import get_robot_variable, get_simple_logger, Singleton, skip_if_dryrun, get_fsm_sw_version
from robot.libraries.BuiltIn import BuiltIn


class AliasNotFoundException(Exception):
    pass


class DirectionNotSupportedException(AliasNotFoundException):
    pass


class ta_tti_parser(with_metaclass(Singleton)):
    """
    Interface for TTI parser and TTI collector
    Full code in latest available version is on gitlab:
    https://wrgitlab.int.net.nokia.com/test_tools/ta_tti_parser
    https://wrgitlab.int.net.nokia.com/test_tools/ta_tti_collector
    """
    ROBOT_LIBRARY_SCOPE = 'GLOBAL'
    ROBOT_LISTENER_API_VERSION = 2

    @skip_if_dryrun
    def __init__(self):
        """Basic initialization."""
        self.ROBOT_LIBRARY_LISTENER = self
        _robot_output_dir = get_robot_variable('OUTPUT_DIR')
        self.robot_output_dir = _robot_output_dir if _robot_output_dir else '/tmp'
        self.logger = get_simple_logger(logger=None, logger_name='tti_parser_interface', stream=True,
                                        full_path=path.join(self.robot_output_dir, 'ta_tti_parser.log'))
        self._dst_logs_path = ''
        self.egate_parser = ta_egate_cmd_parser()
        self.parser = TtiDatParser()
        self.collector = TtiCollector(self.robot_output_dir)
        self.ue_mapping = {}
        self._traces = {}
        self.sim_build = self.detect_sim_type()

    @keyword('Create TTI alias ${name} for eNB-${enb_id:\\d+} [${lncels}]')
    def create_tti_alias(self, name, enb_id, lncels):
        # type: (str, int, str) -> None
        """Identify what and where you need to collect."""
        cells = {}
        for lc in self._string_to_list(lncels):
            _, lncel_id = lc.split('-')
            cells.update({lncel_id: 'DLUL'})

        alias = {name: {'cells': cells, 'enb': enb_id}}
        self.collector.register = alias

    def renew_cell_mapping(self):
        # type: () -> None
        """
        Sometimes after cell reconfiguration or eNB reset cores id are changed.
        Refresh of cell mapping guarantees traces can be collected after such events.
        """
        self.collector.renew_cellmapping()

    @keyword('Start TTI Trace for aliases [${aliases}]')
    def start_tti_trace_for_aliases(self, aliases):
        # type: (str) -> None
        """Start TTI trace on desired cells."""
        for alias in self._string_to_list(aliases):
            self.collector.start_collecting(alias=alias)

    @keyword('Stop TTI Trace for aliases [${aliases}]')
    def stop_tti_trace_for_aliases(self, aliases):
        # type: (str) -> None
        """Stop TTI trace on desired cells."""
        for alias in self._string_to_list(aliases):
            self.collector.stop_collecting(alias=alias)

    def start_tti_on_all_onair_cells(self):
        """Run cell mapping and start TTI traces for all onAir cells."""
        raise NotImplementedError

    def stop_tti_collecting_from_all_cells(self):
        """Stop collecting TTI from all cells."""
        raise NotImplementedError

    # <=><=><=><=> Parser part <=><=><=><=>
    def parse(self, dat_file):
        # type: (str) -> str
        """Parse binary file."""
        return self.parser.parse_file(dat_file)

    @keyword('Save UE_${ue_id} crnti')
    def get_crnti_from_ue_id(self, ue_id):
        # type: (str) -> str
        """Save crnti of UE for later parsing purposes."""
        ue_id = int(ue_id)
        self.ue_mapping[ue_id] = self.translate_ue_alias_to_crnti(ue_id)
        return self.ue_mapping[ue_id]

    def translate_ue_alias_to_crnti(self, ue_id):
        # type: (int) -> int
        """Get crnti of UE from egate or uexgate"""
        if 'CUS' in self.sim_build:
            get_ue_info = BuiltIn().get_library_instance('ta_uexgate').run_uex_command('get_ue_info', id=ue_id)
            crnti = get_ue_info['crnti']
        else:
            ue_disp = ta_egate_cmd_parser().get_command('ue_disp')
            crnti = ue_disp(id=ue_id).execute_and_parse()['C-RNTI']['Value']
        return crnti

    def get_trace(self, alias, direction, ul_pdcch=False):
        # type: (str, str) -> Trace
        """
        Get trace for alias and direction.
        :param alias:
        :param direction:
        :param ul_pdcch:
        :return:
        """
        self._verify_alias_and_direction(alias, direction)
        try:
            trace = self._traces[(alias, direction)]
        except KeyError:
            filenames = self.collector.register[alias][direction.upper()]

            num_of_traces = len(filenames)
            if num_of_traces == 0:
                raise Exception('No {} TTI traces found for alias: {}'.format(direction, alias))
            if num_of_traces == 1:
                parsed_trace = self.parse(filenames[0])
                parsed_trace = self._change_trace_for_ul_pdcch_if_needed(parsed_trace, ul_pdcch)
                trace = Trace(filename=parsed_trace)
            else:
                parsed_files = []
                for fn in filenames:
                    parsed_files.append(self.parse(fn))
                parsed_files = self._change_trace_for_ul_pdcch_if_needed(parsed_files, ul_pdcch)
                merged_file = TxtFileMerger().merge(parsed_files, alias, direction)
                trace = Trace(filename=merged_file)
            self._traces[(alias, direction)] = trace

        self.logger.debug(trace)
        return trace

    # <=><=><=><=> Filters - Field related <=><=><=><=>
    def values_by_field_from_alias(self, alias, direction, field, ue_list=None, unique=False):
        # type: (str, str, str, List[int], bool) -> Filters
        """
        Get values for specific field.
        Limit result to set with setting unique=True.
        :param alias:
        :param direction:
        :param field:
        :param ue_list:
        :param unique: enable/disable set(result)
        :return:
        """
        if direction.lower() == 'ul-pdcch':
            trace = self.get_trace(alias, direction='UL', ul_pdcch=True)
        else:
            trace = self.get_trace(alias, direction)
        if ue_list:
            values = trace.ue(ue_list).values_by_field(field, unique=unique)
        else:
            values = trace.values_by_field(field, unique=unique)
        self.logger.info('Found{}values: {}'.format(' unique ' if unique else ' ', values.result_list))
        return values

    def values_per_alias(self, aliases, direction, field, ue_list):
        # type: (str, str, str, List[int]) -> Iterator[Tuple[str, Filters]]
        """

        :param aliases:
        :param direction:
        :param field:
        :param ue_list:
        :return:
        """
        for alias in self._string_to_list(aliases):
            values = self.values_by_field_from_alias(alias, direction, field, ue_list, unique=True)
            yield alias, values

    def fetch_values_existence(self, aliases, direction, field, exp_values, ue_list=None):
        # type: (str, str, str, str, List[int]) -> Dict[Tuple[str, str], bool]
        """
        Check if value is present.
        Return result and error msg.
        :param aliases:
        :param direction:
        :param field:
        :param exp_values:
        :param ue_list:
        :return:
        """
        exists = {}
        msg = 'Value {} for field {} is {} present in trace {}:{}'
        for alias, values in self.values_per_alias(aliases, direction, field, ue_list):
            for exp_value in self._string_to_list(exp_values):
                exists[(alias, exp_value)] = True if exp_value in values.result_list else False
                presence = '' if exists[(alias, exp_value)] else 'NOT'
                self.logger.debug(msg.format(exp_value, field, presence, alias, direction))
        return exists

    # <=><=><=><=> Keywords <=><=><=><=>
    @keyword('Verify values [${exp_values}] are present in field ${field} for [${aliases}] ${dir_and_ues}')
    def verify_values_are_present(self, exp_values, field, aliases, dir_and_ues):
        """
        Verify if values are present in the field.
        :param exp_values: to be compared with results
        :param field: field name in TTI trace
        :param aliases: list of trace aliases
        :param dir_and_ues: direction of trace DL or UL; list of ues, empty by default
        """
        direction, ue_list = self._get_direction_and_ues(dir_and_ues)
        result = self.fetch_values_existence(aliases, direction, field, exp_values, ue_list)
        assert all(result.values()), 'Value not found for alias where False is present.\n' \
                                     '((alias, exp_value), present_in_trace)\n{}'.format(result.items())

    @keyword('Verify values [${exp_values}] are not present in field ${field} for [${aliases}] ${dir_and_ues}')
    def verify_values_are_not_present(self, exp_values, field, aliases, dir_and_ues):
        """
        Verify if values are not present in the field.
        :param exp_values: to be compared with results
        :param field: field name in TTI trace
        :param aliases: list of trace aliases
        :param dir_and_ues: direction of trace DL or UL; list of ues, empty by default
        """
        direction, ue_list = self._get_direction_and_ues(dir_and_ues)
        result = self.fetch_values_existence(aliases, direction, field, exp_values, ue_list)
        assert not any(result.values()), 'Value found for alias where True is present.\n'\
                                         '((alias, exp_value), present_in_trace?)\n{}'.format(result.items())

    @keyword('Verify values [${exp_values}] occurred ${operator} ${num} times in field ${field} for [${aliases}] ${dir_and_ues}')
    def verify_values_occurred_n_times(self, exp_values, operator, num, field, aliases, dir_and_ues):
        """
        Verify number of occurrences.
        :param exp_values: to be compared with results
        :param operator: eg. ('>', '<', '>=', '<=', '==')
        :param num: expected number of occurrence
        :param field: field name in TTI trace
        :param aliases: list of trace aliases
        :param dir_and_ues: direction of trace DL or UL; list of ues, empty by default
        :return: bool
        """
        valid_op = ('>', '<', '>=', '<=', '==')
        assert operator in valid_op, 'Not recognized math operator: {}, choose from {}'.format(operator, valid_op)

        direction, ue_list = self._get_direction_and_ues(dir_and_ues)
        equations = {s: None for s in valid_op}
        msg = 'Number of occurrences for value {v} is {status}: got: {g}, exp: {op} {n}'
        num = int(num)
        for _, values in self.values_per_alias(aliases, direction, field, ue_list):
            occurrences = Counter(values.result_list)
            for exp_value in self._string_to_list(exp_values):
                occurrence = occurrences[exp_value]
                equations.update({'>': occurrence > num, '<': occurrence < num, '>=': occurrence >= num,
                                  '<=': occurrence <= num, '==': occurrence == num})
                assert equations[operator], \
                    msg.format(v=exp_value, status='different', g=occurrence, op=operator, n=num)
                self.logger.debug(msg.format(v=exp_value, status='valid', g=occurrence, op=operator, n=num))

    @keyword('Verify all values ${operator} ${num} in field ${field} for [${aliases}] ${dir_and_ues}')
    def verify_all_values_meet_condition(self, operator, num, field, aliases, dir_and_ues):
        """
        Check if values will assert equation for specific alias and direction.
        :param operator: eg. ('>', '<', '>=', '<=')
        :param num: int to compare
        :param field: to search for
        :param aliases: list of trace aliases
        :param dir_and_ues: direction of trace DL or UL; list of ues, empty by default
        :return:
        """
        valid_op = ('>', '<', '>=', '<=')
        assert operator in valid_op, 'Not recognized math operator: {}, choose from {}'.format(operator, valid_op)

        direction, ue_list = self._get_direction_and_ues(dir_and_ues)
        info = 'Value for {field} should be {sign} than {num}, found min: {min_v} max: {max_v}'
        equations = {s: None for s in valid_op}
        for _, values in self.values_per_alias(aliases, direction, field, ue_list):
            values = values.result_list
            num = int(num)
            min_v = int(min(values))
            max_v = int(max(values))
            equations.update({'>': min_v > num, '<': max_v < num, '>=': min_v >= num, '<=': max_v <= num})

            assert equations[operator], info.format(field=field, sign=operator, num=num, min_v=min_v, max_v=max_v)

    @keyword('Verify numeric range (${range}) in field ${field} for [${aliases}] ${dir_and_ues}')
    def verify_values_range(self, _range, field, aliases, dir_and_ues):
        """
        Check if values are in range for specific alias and direction.

        :param _range: int, e.g (-50,34)
        :param field: to search for
        :param aliases: list of trace aliases
        :param dir_and_ues: direction of trace DL or UL; list of ues, empty by default
        """
        _min, _max = _range.split(',')
        _min = int(_min)
        _max = int(_max)
        direction, ue_list = self._get_direction_and_ues(dir_and_ues)
        for _, values in self.values_per_alias(aliases, direction, field, ue_list):
            values = [int(v) for v in values.result_list if v.isalnum()]
            min_v = min(values)
            max_v = max(values)
            assert min_v >= _min and max_v <= _max, \
                "Values are outside of valid range.\nMin in logs: {} vs expected min {}\n" \
                "Max in logs: {} vs expected max {}".format(min_v, _min, max_v, _max)

    @keyword('Verify only values [${ev}] optional [${ov}] are present in field ${field} for [${aliases}] ${dir_and_ues}')
    def verify_only_values_are_present(self, ev, ov, field, aliases, dir_and_ues):
        """
        Verify if there are only specified values in selected field.

        :param ev: expected values
        :param ov: optional value
        :param field: to search in
        :param aliases: list of trace aliases
        :param dir_and_ues: direction of trace DL or UL; list of ues, empty by default
        """
        opt_val = self._string_to_list(ov) if ov else ''
        exp_val = self._string_to_list(ev)
        all_expected = set(exp_val).union(set(opt_val))
        direction, ue_list = self._get_direction_and_ues(dir_and_ues)

        new_msg = 'Mandatory value {} {}found for field {} on alias {} and direction {}{}'
        msg = 'Values for field {} on alias {} and direction {} {}:\nexpected: {}\nfound: {}'

        for alias, values in self.values_per_alias(aliases, direction, field, ue_list):
            val = set(values.result_list)
            for mandatory_v in exp_val:
                assert mandatory_v in val, \
                    new_msg.format(mandatory_v, 'not ', field, alias, direction, '\nfound values: {}'.format(val))
                self.logger.debug(new_msg.format(mandatory_v, '', field, alias, direction, ''))
            for v in val:
                assert v in all_expected, msg.format(field, alias, direction, 'differs', all_expected, val)
            self.logger.debug(msg.format(field, alias, direction, 'matches', all_expected, val))

    @staticmethod
    def _string_to_list(str_values, sep=','):
        # type: (str, str) -> List[str]
        """Iterate thru string values from string with separator."""
        return [str_val.strip() for str_val in str_values.split(sep)]

    def _verify_alias_and_direction(self, alias, direction):
        if alias not in self.collector.register:
            raise AliasNotFoundException("Alias '{}' not found. Available aliases: {}".
                                         format(alias, ", ".join(self.collector.register.keys())))
        if direction not in self.collector.register[alias]:
            raise DirectionNotSupportedException("Direction '{}' not found. Available directions: {}".
                                                 format(direction, "UL, DL, PDCCH, UL-PDCCH"))

    def _change_trace_for_ul_pdcch_if_needed(self, parsed_trace, ul_pdcch):
        if ul_pdcch:
            if isinstance(parsed_trace, str):
                return parsed_trace.replace(".txt", "_pdcch.txt")
            if isinstance(parsed_trace, list):
                return [i.replace(".txt", "_pdcch.txt") for i in parsed_trace]
        return parsed_trace

    def _get_direction_and_ues(self, dir_and_ues):
        dir_and_ues = dir_and_ues.replace(' ', '')
        direction, _, ue_list = dir_and_ues.partition('on')
        if ue_list:
            ue_list = [self.ue_mapping[int(ue.rpartition('_')[-1])] for ue in ue_list[1:-1].split(',')]
        return direction, ue_list

    # <=><=><=><=> Robot <=><=><=><=>
    def _start_suite(self, name, attrs):
        self.logger.debug('Starting suite: {}'.format(name))
        self._suite_start_time = datetime.strftime(datetime.now(), '%y%m%d_%H%M%S')

    def _start_test(self, name, attrs):
        self.logger.debug('Starting test: {}'.format(name))

    @skip_if_dryrun
    def _end_test(self, name, attrs):
        self.logger.debug('Ending TC: {}'.format(name))
        self.collector.post_test_cleanup()
        self.logger.debug('After killing servers')
        self._traces.clear()

    def detect_sim_type(self):
        # type: () -> str
        sim_build = 'IPHY'
        try:
            sim_build = get_fsm_sw_version(self.logger, 'iphy')
        except Exception:
            self.logger.warning('Can not detect simulator build, set default as IPHY')
        return sim_build
